<?php
declare(strict_types=1);
if(!defined('PLEKSI_APP')){http_response_code(404);exit;}
function pass_hash(string $p): string {return password_hash(hash('sha256',$p),PASSWORD_DEFAULT);}
function pass_check(mixed $p,string $hash): bool {return is_string($p)&&strlen($p)<=800&&password_verify(hash('sha256',$p),$hash);}
function good_password(mixed $p): bool {return valid_text($p,10,200);}
function accounts_route(string $route,string $method,array $b): void {
 global $db,$user,$config;
 if($route==='/me'&&$method==='GET')out(safe_user($user));
 if($route==='/auth/register'&&$method==='POST'){
  $ph=phone($b['phone']??null);foreach(['firstName','lastName','city','district','neighborhood'] as $key)if(!valid_text($b[$key]??null))fail('Telefon, isim, soyisim, il, ilçe ve mahalle bilgilerini doldurun.');if(!$ph||!good_password($b['password']??null))fail('Geçerli telefon ve en az 10 karakterli şifre girin.');
  try{$id=atomic(function()use($b,$ph,$db){sql("INSERT INTO ph_users(phone,name,first_name,last_name,city,district,neighborhood,password) VALUES(?,?,?,?,?,?,?,?)",[$ph,trim($b['firstName']).' '.trim($b['lastName']),trim($b['firstName']),trim($b['lastName']),trim($b['city']),trim($b['district']),trim($b['neighborhood']),pass_hash($b['password'])]);$id=(int)$db->lastInsertId();notify('member',$id);return $id;});}catch(PDOException $e){if($e->getCode()==='23000')fail('Bu telefon numarasıyla zaten bir başvuru var.',409);throw $e;}
  out(['id'=>$id,'status'=>'pending','message'=>'Üyelik başvurunuz alındı. Yönetici onayından sonra giriş yapabilirsiniz.'],201);
 }
 if($route==='/auth/login'&&$method==='POST'){
  $u=one('SELECT * FROM ph_users WHERE phone=?',[phone($b['phone']??null)??'']);$hash=$u['password']??'$2y$10$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2uheWG/igi.';
  if(!pass_check($b['password']??null,$hash)||!$u)fail('Telefon veya şifre hatalı.',401);if($u['role']!=='admin'&&!is_dealer($u))fail($u['dealer_status']==='pending'?'Üyeliğiniz yönetici onayı bekliyor.':'Üyeliğiniz aktif değil.',403);if($u['must_change_password']&&$u['password_expires']<now_ms())fail('Geçici şifrenizin süresi dolmuş. Yöneticiden yeni şifre isteyin.',403);new_session((int)$u['id']);out(safe_user($u));
 }
 if($route==='/auth/forgot'&&$method==='POST'){$ph=phone($b['phone']??null);if(!$ph||!one("SELECT id FROM ph_users WHERE phone=? AND dealer_status='approved'",[$ph]))fail('Bu numarayla onaylı bir bayi bulunamadı.',404);$adminPhone=setting('admin_whatsapp',one("SELECT phone FROM ph_users WHERE role='admin' ORDER BY id LIMIT 1")['phone']??'');if(!phone($adminPhone))fail('Yönetici WhatsApp numarası henüz tanımlanmamış.',503);out(['url'=>'https://wa.me/'.$adminPhone.'?text='.rawurlencode('Merhaba, şifremi unuttum. Kayıtlı telefon numaram: +'.$ph.'. Şifremi yenilemek için destek rica ediyorum.')]);}
 if($route==='/auth/change-password'&&$method==='POST'){$u=auth();if($u['must_change_password']&&$u['password_expires']<now_ms())fail('Geçici şifrenizin süresi dolmuş.',403);if(!pass_check($b['currentPassword']??null,$u['password']))fail('Mevcut / geçici şifre hatalı.');if(!good_password($b['newPassword']??null)||$b['newPassword']===$b['currentPassword'])fail('Eski şifreden farklı, en az 10 karakterli yeni bir şifre girin.');atomic(function()use($b,$u){sql('UPDATE ph_users SET password=?,must_change_password=0,password_expires=NULL WHERE id=?',[pass_hash($b['newPassword']),$u['id']]);sql('DELETE FROM ph_sessions WHERE user_id=?',[$u['id']]);});new_session((int)$u['id']);out(['ok'=>true]);}
 if($route==='/logout'&&$method==='POST'){if(isset($_COOKIE['ph_session']))sql('DELETE FROM ph_sessions WHERE token=?',[hash('sha256',$_COOKIE['ph_session'])]);setcookie('ph_session','',['expires'=>1,'path'=>($config['base_path']?:'').'/','secure'=>(bool)$config['secure_cookie'],'httponly'=>true,'samesite'=>'Lax']);out(['ok'=>true]);}
 if($route==='/admin/dealers'&&$method==='GET')out(array_map('safe_user',rows("SELECT * FROM ph_users WHERE role!='admin' ORDER BY id DESC")));
 if(preg_match('~^/admin/dealers/(\d+)$~',$route,$m)&&$method==='PATCH'){$status=$b['status']??'';if(!in_array($status,['approved','pending','rejected'],true))fail('Geçersiz durum.');$u=one("SELECT id FROM ph_users WHERE id=? AND role!='admin'",[$m[1]]);if(!$u)fail('Üye bulunamadı.',404);atomic(function()use($status,$m){sql('UPDATE ph_users SET dealer_status=? WHERE id=?',[$status,$m[1]]);if($status!=='approved')sql('DELETE FROM ph_sessions WHERE user_id=?',[$m[1]]);});out(['ok'=>true]);}
 if(preg_match('~^/admin/dealers/(\d+)/reset-password$~',$route,$m)&&$method==='POST'){$target=one("SELECT * FROM ph_users WHERE id=? AND role!='admin' AND dealer_status='approved'",[$m[1]]);if(!$target)fail('Geçici şifre için onaylı bir komisyoncu seçin.');$password=rtrim(strtr(base64_encode(random_bytes(15)),'+/','-_'),'=');$expires=now_ms()+86400000;atomic(function()use($target,$password,$expires){sql('UPDATE ph_users SET password=?,must_change_password=1,password_expires=? WHERE id=?',[pass_hash($password),$expires,$target['id']]);sql('DELETE FROM ph_sessions WHERE user_id=?',[$target['id']]);});out(['temporaryPassword'=>$password,'expiresAt'=>$expires,'phone'=>$target['phone']]);}
 if($route==='/delivery-options'&&$method==='GET')out(delivery_options());
 if($route==='/admin/settings'&&$method==='GET')out(['adminWhatsapp'=>setting('admin_whatsapp',one("SELECT phone FROM ph_users WHERE role='admin' ORDER BY id LIMIT 1")['phone']??''),'deliveryOptions'=>delivery_options()]);
 if($route==='/admin/settings'&&$method==='PUT'){if(isset($b['adminWhatsapp'])&&!phone($b['adminWhatsapp']))fail('Geçerli yönetici cep telefonu girin.');if(isset($b['deliveryFees'])){foreach(['pickup','cargo','address'] as $key)if(!money_value($b['deliveryFees'][$key]??null,0,100000))fail('Teslimat ücretlerini kontrol edin.');}atomic(function()use($b){if(isset($b['adminWhatsapp']))set_setting('admin_whatsapp',phone($b['adminWhatsapp']));if(isset($b['deliveryFees']))set_setting('delivery_fees',enc($b['deliveryFees']));});out(['ok'=>true]);}
}
